const { randomUUID } = require('crypto');

return [{
  json: {
    ...$json,
    internal_claim_id: randomUUID()
  },
  binary: $binary
}];

const items = $input.all();

return items.map((item) => ({
  json: {

    internal_claim_id:
      item?.json?.internal_claim_id,

    claim_id:
      item?.json?.claim_id,

    event_type: "INGESTION_SUCCESS",

    workflow_stage: "INGESTION",

    severity: "INFO",

    success: true,

    claim_status: "RECEIVED",

    message: "Claim successfully ingested.",

    timestamp: new Date().toISOString()

  }
}));

return {
  json: {

    internal_claim_id: $json.internal_claim_id,

    claim_id: $json.claim_id,

    workflow_stage: $json.workflow_stage,

    event_type: $json.event_type,

    severity: $json.severity,

    message: $json.message,

    event_status: $json.success ? 'SUCCESS' : 'FAILED',

    metadata: {
      source_field: $json.source_field,
      file_name: $json.file_name,
      mime_type: $json.mime_type,
      storage_key: $json.storage_key
    },

    created_at: new Date().toISOString()

  }
};

const aiDecision =
  $json.decision;

const fraudRisk =
  $json.fraud_level;

const humanReview =
  $json.human_review_required === 'Yes';

const coverageEligibility =
  $json.coverage_eligibility;



let current_route =
  'AUTO_APPROVAL';



// =====================================
// HIGH RISK / FRAUD
// =====================================

if (
  aiDecision === 'FRAUD_INVESTIGATION'
  ||
  fraudRisk?.toLowerCase() === 'high'
) {

  current_route =
    'FRAUD_INVESTIGATION';

}



// =====================================
// HUMAN REVIEW
// =====================================

else if (
  aiDecision === 'HUMAN_REVIEW'
  ||
  humanReview === true
) {

  current_route =
    'MANUAL_REVIEW';

}



// =====================================
// AUTO APPROVE
// =====================================

else if (
  aiDecision === 'AUTO_APPROVE'
  &&
  humanReview === false
  &&
  fraudRisk?.toLowerCase() !== 'high'
  &&
  coverageEligibility !== 'Ineligible'
) {

  current_route =
    'AUTO_APPROVAL';

}



return [{
  json: {
    ...$json,

    governance: {

      ai_decision:
        aiDecision,

      fraud_risk:
        fraudRisk,

      human_review_required:
        humanReview,

      coverage_eligibility:
        coverageEligibility,

      route_to:
        current_route
    }
  }
}];
